from common10 import *
from analysis10 import rows
import sqlite3,html
from ledger_core import footprint
from shapely.geometry import Polygon,mapping
from shapely import set_precision

def render(out,data):
 payload={}
 for name,item in data['cases'].items():
  p=ROOT/item['path'];db=sqlite3.connect(p/'ledger/ledger.sqlite');samples=[];cfg=read(p/'scene/tool.json');goals={k:json.loads(g) for k,g in db.execute('SELECT key,goal FROM jobs')}
  for t,key,q,accepted,reason,obs in db.execute('SELECT t,key,quantity,accepted,reason,observation FROM events ORDER BY t'):
   o=json.loads(obs);ctx=o.get('context');geometry=None
   if accepted and cfg['vehicle']=='ackermann' and ctx:
    precision=cfg['ledger_precision_m'];erosion=cfg['pose_erosion_m']+math.hypot(.35,.45)*cfg['yaw_erosion_rad']+precision;area=footprint(*ctx['tool_xy'],ctx['yaw'],.70,.90,erosion).intersection(Polygon(goals[key]['area']).buffer(-precision));geometry=mapping(set_precision(area,precision))
   samples.append(dict(t=t,key=key,q=q,ok=bool(accepted),reason=reason,xy=ctx['tool_xy'] if ctx else None,yaw=ctx['yaw'] if ctx else 0,geometry=geometry))
  goals={k:json.loads(g) for k,g in db.execute('SELECT key,goal FROM jobs')};transitions=[dict(key=k,t=t,state=state,reason=reason) for k,t,state,reason in db.execute('SELECT key,t,status,reason FROM transitions')];db.close();physical=rows(p/'tool_evaluation/physical.jsonl');payload[name]=dict(metrics=item['metrics'],transitions=transitions,samples=samples,goals=goals,physical=[dict(t=x['t'],xy=[x['tool_xyz'][0]-28,x['tool_xyz'][1]-14],yaw=x['tool_yaw'],on=x['on'],rpm=x['rpm_rad_s']) for x in physical],events=read(p/'client/result.json')['events'])
 template=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>S10 工具动作与有效账本</title><style>
*{box-sizing:border-box}body{font-family:system-ui,"Noto Sans CJK SC",sans-serif;background:#eef3f6;color:#173044;margin:0;padding:25px;max-width:1500px;margin:auto}h1{margin:0;font-size:30px}p{line-height:1.7}header,.card{background:white;padding:22px;border-radius:14px;margin-bottom:16px}small{color:#516777}.row{display:grid;grid-template-columns:1fr 1fr;gap:18px}.controls{display:flex;align-items:center;gap:20px;flex-wrap:wrap}select,button{padding:9px;border-radius:6px;border:1px solid #b6c9d5;background:white}input{width:40%}canvas{width:100%;height:340px;border:1px solid #d9e4ea;border-radius:8px}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:9px;border-bottom:1px solid #e4ecf1}th{background:#f1f6f9}.pass{color:#08795d}.fail{color:#a92539}pre{white-space:pre-wrap;font-size:13px}#events{max-height:260px;overflow:auto}.legend{font-size:14px}.dot{font-weight:bold}@media(max-width:850px){.row{grid-template-columns:1fr}body{padding:12px}}
</style><header><small>实测回放 · 离线可用 · S10 / ROS 2 + Gazebo + SQLite</small><h1>喷洒、割草与有效作业账本</h1><p>__STATUS__ · 自动与人工状态分别记录。拖动时间查看确认作业量及残余；绿色仅来自在线反馈，蓝色是独立物理评分，二者的数据通道隔离。</p><div class="controls"><label>案例 <select id="case"></select></label><button id="play">播放 / 暂停</button><input id="time" type="range" min="0" step="0.05"><b id="clock"></b></div></header>
<div class="row"><div class="card"><h3>工具作用与观测足迹（地图局部）</h3><canvas id="map" width="650" height="340"></canvas><p class="legend"><span style="color:#099879">■ 在线确认足迹</span>　<span style="color:#317bbe">■ 物理作用范围</span>　虚线：请求区域。重复足迹取并集，不按帧重复加面积。</p></div><div class="card"><h3>按幂等键累计的确认作业量</h3><canvas id="chart" width="650" height="340"></canvas><p id="stats"></p></div></div>
<div class="card"><h3>任务、终态与残余</h3><table><thead><tr><th>幂等键</th><th>当前状态</th><th>确认量</th><th>目标量</th><th>未确认量</th><th>最终物理作用量</th></tr></thead><tbody id="jobs"></tbody></table><p><small>喷洒单位为归一化剂量秒（额定流量 × 时间），不是升；割草单位 m²。物理作用量包括未计入账本的启动、停车尾迹。LOST / RECOVERY_REQUIRED 必须核查，不能自动当成未喷洒。</small></p></div>
<div class="row"><div class="card"><h3>时刻之前的动作事件</h3><pre id="events"></pre></div><div class="card"><h3>本例验收检查</h3><div id="checks"></div></div></div>
<div class="card"><h3>证据范围</h3><p>沿用 S03 工具尺寸、S04 噪声、S05–S08 定位和 S09 感知。当前为 A 区附近的授权诊断小范围任务，不代表两区完整自主作业。目标由当前在线估计选定；近景目标条件使用显式诊断预设，未实现植物识别、机械臂、真实液体/草体、闭环避障或 VLA。95% 是本次割草小条带的完成条件；剩余几何仍保留。</p><p>中断后的安全重试会保留已经确认的工作；未确认的实际作用不能凭命令补记。停止工具须由转速反馈确认。报告没有访问在线控制接口。</p></div>
<script>const data=__DATA__;const by=id=>document.getElementById(id);let playing=false;const colors=['#099879','#b86520','#725ac1','#b13b58','#2687a5','#5868bd','#7c8932'];
Object.keys(data).forEach(k=>{let o=document.createElement('option');o.value=k;o.textContent=k;by('case').append(o)});
function shape(ctx,poly,project,fill){if(!poly.length)return;ctx.beginPath();poly.forEach((p,i)=>{let q=project(p);if(i)ctx.lineTo(...q);else ctx.moveTo(...q)});ctx.closePath();if(fill)ctx.fill();else ctx.stroke()}
function geo(ctx,g,project){if(!g)return;let ps=g.type==='Polygon'?[g.coordinates]:g.type==='MultiPolygon'?g.coordinates:[];ps.forEach(poly=>{ctx.beginPath();poly.forEach(ring=>{ring.forEach((p,i)=>{let q=project(p);if(i)ctx.lineTo(...q);else ctx.moveTo(...q)});ctx.closePath()});ctx.fill('evenodd')})}
function rect(xy,yaw,l,w){return [[-l/2,-w/2],[l/2,-w/2],[l/2,w/2],[-l/2,w/2]].map(([x,y])=>[xy[0]+x*Math.cos(yaw)-y*Math.sin(yaw),xy[1]+x*Math.sin(yaw)+y*Math.cos(yaw)])}
function render(){let d=data[by('case').value];if(!d)return;let max=Math.max(1,...d.events.map(x=>x.t),...d.samples.map(x=>x.t));by('time').max=max;let t=Math.min(+by('time').value,max);by('clock').textContent=t.toFixed(2)+' 仿真秒';const mowing=d.metrics.vehicle==='ackermann';let cv=by('map'),ctx=cv.getContext('2d');ctx.clearRect(0,0,cv.width,cv.height);ctx.fillStyle='#f5f9fc';ctx.fillRect(0,0,cv.width,cv.height);let all=Object.values(d.goals).flatMap(g=>g.area.length?g.area:[g.target.slice(0,2)]);if(!all.length)all=[[0,0]];let xs=all.map(p=>p[0]),ys=all.map(p=>p[1]),xmin=Math.min(...xs)-.6,xmax=Math.max(...xs)+.6,ymin=Math.min(...ys)-.6,ymax=Math.max(...ys)+.6;let scale=Math.min(590/(xmax-xmin),280/(ymax-ymin));const project=p=>[30+(p[0]-xmin)*scale,310-(p[1]-ymin)*scale];ctx.strokeStyle='#728799';ctx.setLineDash([5,4]);Object.values(d.goals).forEach(g=>{if(g.area.length)shape(ctx,g.area,project,false);else{let p=project(g.target);ctx.beginPath();ctx.arc(...p,.2*scale,0,7);ctx.stroke()}});ctx.setLineDash([]);
ctx.fillStyle='#8eb8dc';d.physical.filter(x=>x.t<=t&&x.rpm>=8).forEach(x=>{if(mowing)shape(ctx,rect(x.xy,x.yaw,.70,.90),project,true);else{let p=project(x.xy);ctx.beginPath();ctx.arc(...p,.20*scale,0,7);ctx.fill()}});ctx.fillStyle='#099879';d.samples.filter(x=>x.t<=t&&x.ok&&x.xy).forEach(x=>{if(mowing)geo(ctx,x.geometry,project);else{let p=project(x.xy);ctx.beginPath();ctx.arc(...p,.08*scale,0,7);ctx.fill()}});ctx.strokeStyle='#233d50';ctx.setLineDash([4,3]);Object.values(d.goals).forEach(g=>{if(g.area.length)shape(ctx,g.area,project,false);else{let p=project(g.target);ctx.beginPath();ctx.arc(...p,.2*scale,0,7);ctx.stroke()}});ctx.setLineDash([]);ctx.fillStyle='#344d60';ctx.fillText('map x / y，单位米；局部自动缩放',20,22);
cv=by('chart');ctx=cv.getContext('2d');ctx.clearRect(0,0,cv.width,cv.height);let ymaxq=Math.max(mowing?.1:2.1,...Object.values(d.goals).map(g=>g.requested_quantity))*1.1;ctx.strokeStyle='#d3e0e9';for(let j=0;j<5;j++){let y=300-j*65;ctx.beginPath();ctx.moveTo(50,y);ctx.lineTo(630,y);ctx.stroke();ctx.fillStyle='#587084';ctx.fillText((j*ymaxq/4).toFixed(2),10,y)}Object.keys(d.goals).forEach((k,i)=>{ctx.strokeStyle=colors[i%colors.length];ctx.beginPath();let rows=d.samples.filter(x=>x.key===k&&x.t<=t);rows.forEach((x,j)=>{let p=[50+x.t/max*580,300-x.q/ymaxq*260];if(j)ctx.lineTo(...p);else ctx.moveTo(...p)});ctx.stroke()});ctx.fillStyle='#344d60';ctx.fillText(mowing?'确认面积 m²':'确认剂量秒',52,24);ctx.fillText('仿真时间 s',540,330);
by('jobs').innerHTML='';Object.entries(d.goals).forEach(([k,g],i)=>{let rr=d.samples.filter(x=>x.key===k&&x.t<=t),q=rr.length?rr.at(-1).q:0;let events=d.transitions.filter(x=>x.key===k&&x.t<=t);let state=events.length?events.at(-1).state:'PENDING';let physical=d.metrics.comparisons.find(x=>x.key===k);let tr=document.createElement('tr');[k,state,q.toFixed(3),g.requested_quantity.toFixed(3),Math.max(0,g.requested_quantity-q).toFixed(3),(physical?.physical||0).toFixed(3)].forEach(v=>{let td=document.createElement('td');td.textContent=v;tr.append(td)});tr.style.borderLeft='5px solid '+colors[i%colors.length];by('jobs').append(tr)});
by('events').textContent=d.events.filter(x=>x.t<=t&&['result','fault','cancel','request','segment_turn'].includes(x.event)).map(x=>`${x.t.toFixed(2)}s ${x.label||x.mode||''} ${x.state||x.event} ${x.reason||''}`).join('\n');by('checks').innerHTML=Object.entries(d.metrics.checks).map(([k,v])=>`<p class="${v?'pass':'fail'}">${v?'✓':'✗'} ${k}</p>`).join('');by('stats').textContent=`实测时长 ${d.metrics.sim_seconds} 仿真秒；移动 ${d.metrics.distance_m.toFixed(3)} m；峰值内存 ${d.metrics.peak_rss_gib.toFixed(2)} GiB；${d.metrics.credited_samples} 条确认观测。`;document.body.dataset.rendered='true'}
by('case').onchange=()=>{by('time').value=0;render()};by('time').oninput=render;by('play').onclick=()=>playing=!playing;setInterval(()=>{if(playing){by('time').value=Math.min(+by('time').max,+by('time').value+.25);render();if(+by('time').value>=+by('time').max)playing=false}},100);by('time').max=100000;by('time').value=100000;render();</script></html>'''
 (out/'index.html').write_text(template.replace('__STATUS__',html.escape(data['status'])+' / 人工 NOT_CHECKED').replace('__DATA__',json.dumps(payload,ensure_ascii=False).replace('</','<\\/')))
